package net.civeira.phylax.features.access.consentpurpose.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.features.access.consentpurpose.domain.ConsentPurposeKeyOptions;

class KeyVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property key of consent purpose ")
  void test_key_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> KeyVO.tryFrom("_MARKETING_"));
    Assertions.assertEquals(ConsentPurposeKeyOptions.MARKETING,
        KeyVO.tryFrom("MARKETING").getKey());
    Assertions.assertThrows(ConstraintException.class, () -> KeyVO.tryFrom(null));
    Assertions.assertEquals(ConsentPurposeKeyOptions.MARKETING,
        KeyVO.from(ConsentPurposeKeyOptions.MARKETING).getKey());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> KeyVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + ConsentPurposeKeyOptions.MARKETING + "]",
        KeyVO.from(ConsentPurposeKeyOptions.MARKETING).toString());
  }
}
